  "community.prompt.image": "请基于「{title}」模板，为我生成一张「[请填写图片主题]」图片。\n\n【创作目的】\n[填写这张图片用于什么场景，以及希望传达的核心信息]\n\n【画面主体】\n[填写主体、人物、产品或关键物体，以及必须保留的细节]\n\n【场景与构图】\n[填写环境、景别、视角、主体位置和画面留白要求]\n\n【风格与氛围】\n保留此模板的核心视觉语言、色彩关系和质感；根据新主题调整内容，不要照抄示例元素。\n\n【文字信息】\n[填写需要出现在画面中的准确文字；没有则写“无文字”]\n\n【输出要求】\n[填写画幅比例、尺寸、清晰度和使用平台]\n\n【避免】\n不要添加未提供的品牌标识、虚构文字、水印或无关装饰。",
  "community.prompt.motion": "请基于「{title}」模板，为我制作一段「[请填写动效主题]」动效。\n\n【传播目标】\n[填写这段动效要传达的信息和使用场景]\n\n【核心内容】\n[填写必须出现的文字、品牌元素、产品或素材]\n\n【节奏与镜头】\n[填写时长、画幅、节奏、关键转场和结尾状态]\n\n【设计要求】\n保留此模板的核心视觉语言和运动规律，根据真实内容重新编排，不要照抄示例文案。\n\n【输出要求】\n[填写尺寸、帧率、格式、是否循环以及是否需要透明背景]",
  "community.prompt.deliverable.slides": "一份完整的幻灯片",
  "community.prompt.deliverable.page": "一个可交付网页",
  "community.prompt.document": "请基于「{title}」模板，为我制作{deliverable}，主题是「[请填写主题、产品或项目名称]」。\n\n【使用场景】\n[填写汇报、提案、官网、活动页面等具体场景]\n\n【目标受众】\n[填写受众角色，以及他们最关心的问题]\n\n【核心目标】\n[填写看完后希望受众理解、相信或采取的行动]\n\n【核心内容】\n1. [必须传达的关键结论]\n2. [支撑结论的事实、数据或功能]\n3. [需要重点展示的案例、流程或卖点]\n\n【现有素材】\n[粘贴已有文案、数据、图片链接或参考资料；缺失信息请明确标注，不要虚构]\n\n【设计要求】\n保留此模板的核心视觉语言、版式节奏和交互特征；根据真实内容重新组织信息层级，不要照抄示例文案，不要使用 Lorem ipsum 或无意义占位内容。\n\n【交付要求】\n[填写页数或页面范围、尺寸、设备适配、文件格式和截止时间]",
